import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor who will be owner (to call pause/unpause) as an address
    function testFuzz_property(address owner) public {
        // keep owner non-zero to be able to initialize as msg.sender
        vm.assume(owner != address(0));

        // initialize contract as 'owner'
        vm.prank(owner);
        c.initialize(1, 2, "vt", owner);

        // At this point paused should be false
        bool pausedAfterInit;
        try c.paused() returns (bool v) { pausedAfterInit = v; } catch { pausedAfterInit = false; }

        // invariant: immediately after initialization, paused() must equal false
        // now perform a pause via owner
        vm.prank(owner);
        c.pause();

        bool pausedAfterPause;
        try c.paused() returns (bool v2) { pausedAfterPause = v2; } catch { pausedAfterPause = false; }

        // exactly one assertion: For the reference implementation, pausedAfterInit == false and pausedAfterPause == true
        // The mutant inverts the stored flag and will make this assertion fail for some inputs (owner choices)
        assertTrue(pausedAfterInit == false && pausedAfterPause == true);
    }
