pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // fuzz parameter: a boolean telling whether we call pause (true) or unPause (false)
    function testFuzz_property(bool doPause) public {
        // admissible domain: none to restrict — both branches are valid

        // Only the owner can pause/unpause; contract was initialized in constructor via _disableInitializers,
        // but owner is set when initialize is called. We need to make msg.sender the owner by calling initialize.
        // initialize is external and uses initializer modifier; call it from this test (this becomes owner).
        // Provide reasonable values for params — these can be constants as they are not the fuzzing target.
        c.initialize(1, 2, "vtype", address(0x100));

        // Now this test contract (address(this)) is owner. Depending on doPause we call pause() or unPause().
        if (doPause) {
            c.pause();
        } else {
            // ensure contract is paused first, then unpause to test unPause path deterministically
            c.pause();
            c.unPause();
        }

        // Now read paused() through try/catch to satisfy the rule form; paused() is view and should not revert.
        bool ok;
        try c.paused() returns (bool p) {
            ok = true;
            // For the reference contract: if we called pause (doPause==true) paused() must be true;
            // if we called unPause (doPause==false) paused() must be false.
            // For the mutant, the returned value will be inverted for at least one branch.
            if (doPause) {
                assertTrue(p, "expected paused() == true after pause()");
            } else {
                assertTrue(!p, "expected paused() == false after unPause()");
            }
        } catch {
            // paused() should not revert in the reference for any admissible input
            ok = false;
            assertTrue(ok, "paused() reverted unexpectedly");
        }
    }
}

