import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: a boolean choosePause and an address ownerCandidate
    // choosePause: if true, we call pause(); if false, we call unPause();
    // ownerCandidate is fuzzed to be the caller who will attempt to perform the action.
    function testFuzz_property(bool choosePause, address ownerCandidate) public {
        // admissible domain: ownerCandidate must be non-zero (EOA) and not equal to address(0)
        vm.assume(ownerCandidate != address(0));

        // The initialize function sets msg.sender as owner. We must initialize from the same owner we will use.
        vm.prank(ownerCandidate);
        c.initialize({
            credChainId_: 1,
            credId_: 1,
            verificationType_: "v",
            protocolFeeDestination_: ownerCandidate
        });

        // Now ownerCandidate is the owner. Depending on the fuzzed boolean, call pause() or unPause().
        vm.prank(ownerCandidate);
        if (choosePause) {
            c.pause();
        } else {
            // ensure contract not paused first to make unPause valid: call pause then unPause when needed
            // but we want to test unPause path as well: if contract starts unpaused, calling unPause would revert.
            // So make sure we pause first then unPause to produce a valid sequence.
            c.pause();
            vm.prank(ownerCandidate);
            c.unPause();
        }

        // Exactly one assertion: the public paused() must equal the stored state implied by the sequence we executed.
        // For the reference contract: if choosePause==true then paused() == true, else paused() == false.
        bool reported = c.paused();
        if (choosePause) {
            assertTrue(reported);
        } else {
            assertTrue(!reported);
        }
    }
}

