        bool ok;
        // call getRoyalties and record whether it reverted
        try c.getRoyalties(tokenId) returns (C.RoyaltyConfiguration memory) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference C (correct) is INITIALIZABLE and its getRoyalties MUST revert when not initialized.
        // So for the reference implementation ok must be false for ALL tokenId. The mutant returns true for some tokenIds.
        assertTrue(!ok);
    }
}
